import java.nio.file.*;import java.util.*;
public class ReferenceGolden {public static void main(String[] args)throws Exception {List<String> out=new ArrayList<>();for(String line:Files.readAllLines(Path.of(args[0]))){String[] x=line.split(",");int level=Integer.parseInt(x[0]);double base=Double.parseDouble(x[1]),scale=Double.parseDouble(x[2]);out.add(Double.toString(Math.rint(Math.pow(1.1,level)*((1+.4*level)*base)*scale)));}Files.writeString(Path.of(args[1]),"{\"values\":["+String.join(",",out)+"]}");List<String> p=new ArrayList<>();for(int l=0;l<=30;l++)p.add(Double.toString(Math.pow(1.1,l)));Files.writeString(Path.of(args[2]),String.join(",",p));}}
